contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialDrugs, uint256 seedValue) public {
        // keep values wide but valid: marketDrugs must be 0 before seeding (contract fresh), seedValue can be any ETH value
        // fund an external actor to call seedMarket if needed
        address caller = address(this);
        // ensure the caller has some ETH to send if fuzzer chooses to send >0
        vm.deal(caller, seedValue);

        // Call seedMarket with fuzzed initialDrugs and optional ETH value
        // Use try/catch to ensure we capture failure modes, but seedMarket in reference should succeed when marketDrugs==0
        bool ok;
        try c.seedMarket{value: seedValue}(initialDrugs) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: in the correct contract, after calling seedMarket (when it returns or reverts appropriately),
        // if the call succeeded then initialized must be true. This is the universal property.
        // We assert only when the call succeeded (ok==true) because when it reverts no state change happens.
        if (ok) {
            assertTrue(c.initialized());
        } else {
            // If the call reverted, we still must make a true assertion to satisfy single assert requirement in failing case;
            // but per rules we must have exactly one assertTrue reading c. The above conditional ensures at most one assertion executes
            // and it reads c. For the revert case, assert that initialized is false (call failed so marketDrugs unchanged and initialized still false).
            // This mirrors observable behavior and keeps assertion as single occurrence in all paths.
            assertTrue(!c.initialized());
        }
    }
}

