        // when called by the caller. To invoke it as `caller`, the verifier
        // will set the transaction sender accordingly when exploring.

        // State-changing call: attempt to set ceoAddress to caller
        c.DrugDealer();

        // Observe publicly available ceoAddress and assert it equals the caller.
        // On the original contract P this holds for every caller (it requires msg.sender == ceoAddress
        // but that permits the current ceo to call and set; however the original also sets
        // ceoAddress = msg.sender, so after the call ceoAddress == caller). The mutant M
        // forbids the current CEO from calling, breaking the general rule in some cases.
        assert(c.ceoAddress() == caller);
    }

    // allow receiving ETH if verifier wants to send value in future tests
    receive() external payable {}
}
